export function renderChart(e){if(!e||!e.length)return"<svg width='320' height='80'></svg>";const t=Math.max(...e,1),n=e.map((n,r)=>`<rect x='${8*r}' y='${80-70*n/t}' width='6' height='${70*n/t}' fill='#0a7'/>`).join("");return`<svg width='${8*e.length}' height='80'>${n}</svg>`}
